private async buildStoryTesterMap(featureId: number): Promise<Record<number, string>> {
  const storyIds = await this.client.getStoryIdsByFeature(featureId);
  const storyTester: Record<number, string> = {};

  for (const storyId of storyIds.sort((a, b) => a - b)) {
    const wi = await this.client.getWorkItemWithRelations(storyId);
    // Hierarchy-Forward = parent -> child; these are the story's direct children.
    const childIds = this.client.extractRelationIds(wi.relations || [], 'System.LinkTypes.Hierarchy-Forward');
    if (childIds.length === 0) continue; // no children -> story stays absent from the map

    // Batch-fetch only the fields we need; ADO returns each work item's fields under child.fields.
    const children = await this.client.getWorkItemsBatch(childIds, [
      'System.Id', 'System.Title', 'System.WorkItemType', 'System.AssignedTo',
    ]);

    for (const child of children) {
      const f = child.fields;
      const title = (f['System.Title'] || '').toLowerCase();
      // The authoring owner lives on the 'QA_Test Creation' Task, not on the story itself.
      if (f['System.WorkItemType'] === 'Task' && title.includes('qa_test creation')) {
        // System.AssignedTo is an identity OBJECT, not a string - extract the display name.
        storyTester[storyId] = this.client.extractDisplayName(f['System.AssignedTo']);
        break; // first matching Task wins; it's authoritative for this story
      }
    }
  }
  return storyTester;
}

for (const tc of suiteTCs) {
  const tcId = tc.workItem?.id;
  const title = tc.workItem?.name || '';
  // Story ID is parsed out of the title text; if it can't be read, the case is left un-audited below.
  const storyId = this.extractStoryIdFromTitle(title);

  const wi = await this.client.getWorkItemWithRelations(tcId);
  // From a TEST CASE's side, the correct link to its story is TestedBy-Reverse...
  const testedByReverse = this.client.extractRelationIds(wi.relations || [], 'Microsoft.VSTS.Common.TestedBy-Reverse');
  // ...and a TestedBy-Forward on the test case means it was linked backwards.
  const testedByForward = this.client.extractRelationIds(wi.relations || [], 'Microsoft.VSTS.Common.TestedBy-Forward');

  let missingLink = false, wrongLink = false, needsRename = false;
  if (storyId) { // only audit cases whose story ID we could parse
    const hasCorrectLink = testedByReverse.includes(storyId);
    const hasWrongLink = testedByForward.includes(storyId);
    if (!hasCorrectLink && !hasWrongLink) missingLink = true; // no link either direction
    if (hasWrongLink && !hasCorrectLink) wrongLink = true;    // linked, but backwards

    // Naming check is independent of the link check.
    const correctPrefix = `TC_US${storyId}_`;
    if (!title.startsWith(correctPrefix)) needsRename = true;
  }
  if (missingLink || wrongLink || needsRename) {
    issues.push({ tcId, title, storyId, missingLink, wrongLink, needsRename });
  }
}

private normalizeTitle(title: string, storyId: number): string {
  const correctPrefix = `TC_US${storyId}_`;
  if (title.startsWith(correctPrefix)) return title; // already correct - idempotency guard, makes re-runs safe

  // TC_US<wrong-number>_ : _? allows a stray underscore, [\s_] eats space-or-underscore; replace drops the wrong number.
  if (title.match(/^TC_US_?\d+[\s_]/)) {
    return title.replace(/^TC_US_?\d+[\s_]+/, correctPrefix);
  }
  // TC_UC... : common typo of TC_US; same replace, discarding the bad prefix.
  if (title.match(/^TC_UC_?\d+[\s_]/)) {
    return title.replace(/^TC_UC_?\d+[\s_]+/, correctPrefix);
  }
  // US<number>_ : only the TC_ tag is missing, so prepend rather than replace.
  if (title.match(/^US\d+_/)) {
    return 'TC_' + title;
  }
  // No recognizable prefix - prepend the correct one, keeping the original descriptive text.
  return correctPrefix + title;
}

private async reassignMode(planId: number, suiteId: number, reassignMapStr: string, featureId: number, dryRun: boolean) {
  // Step 1: update the QA_Test Creation task's AssignedTo.
  // 'replace' (not 'add') because the field already holds an owner.
  await this.client.updateWorkItem(qaTaskId, [
    { op: 'replace', path: '/fields/System.AssignedTo', value: newTester },
  ]);

  // Step 2: update every linked checklist's AssignedTo (same replace pattern, per TC)
  // ...

  // Step 3: test points are NOT work items - they live on the plan/suite with their own
  // tester identity, so they use a separate API keyed by POINT id, not work-item id.
  const allPoints = await this.client.getTestPointsPaginated(suiteId, planId);
  const pointUpdates = allPoints
    // Only touch points whose test case is in this reassignment; leave the rest alone.
    .filter(pt => tcNewTester[pt.testCaseReference?.id])
    .map(pt => ({ id: pt.id, tester: { displayName: tcNewTester[pt.testCaseReference.id] } }));
  await this.client.updateTestPoints(planId, suiteId, pointUpdates);
}

private async addTestCases(planId: number, suiteId: number, ids: number[], dryRun: boolean, configId?: number): Promise<void> {
  // De-dupe first: adding an already-present case is a no-op in ADO, so this keeps the op idempotent.
  const unique = Array.from(new Set(ids));
  if (dryRun) return; // preview is truly read-only - bail before any write

  let added = 0;
  for (let i = 0; i < unique.length; i += BATCH_SIZE) {
    const batch = unique.slice(i, i + BATCH_SIZE);
    await this.client.addTestCasesToSuite(planId, suiteId, batch, configId);
    added += batch.length;
    // Throttle BETWEEN batches to stay under ADO rate limits (bulk writes can 429);
    // the guard skips the pause after the last chunk.
    if (i + BATCH_SIZE < unique.length) await this.sleep(BATCH_DELAY_MS);
  }
}
